  forallb (fun seg => negb (seg_writable seg) || seg_readable seg)%bool segs = true -> APSXK.segs_wr_ok segs.
Proof.
  intros segs H seg Hin Hw. pose proof (proj1 (forallb_forall _ _) H seg Hin) as Hs. cbn beta in Hs.
