Lemma drv_chk_HSA : forall r h, 0 <= r <= 1 -> (h < 2)%nat -> drv_chk r (HSA r h) = true.
Proof. intros r h Hr Hh. assert (r = 0 \/ r = 1) as [-> | ->] by lia; destruct h as [|[|h]]; try lia; vm_compute; reflexivity. Qed.
